import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const b=JSON.parse('{"title":"Kebab","description":"","frontmatter":{},"headers":[],"relativePath":"components/kebab.md","filePath":"components/kebab.md"}'),i={name:"components/kebab.md"};function n(r,e,c,s,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="kebab" tabindex="-1">Kebab <a class="header-anchor" href="#kebab" aria-label="Permalink to &quot;Kebab&quot;">​</a></h1><p>Kebab is the menu of actions on an item of a list or a card.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it at the right end of an item. It is also where a destructive action on the item is reached, besides a context menu or the Delete key; such an action never goes in a Footer. The actions on several selected items are a <a href="./bulk">Bulk</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>actions</code></td><td>settings, share, copy, move, delete</td><td>The actions to offer</td></tr><tr><td><code>onaction</code></td><td></td><td>Called with the chosen action</td></tr><tr><td><code>items</code></td><td></td><td>A menu drawn from a model (<code>MenuModel[]</code>) instead of the actions</td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the chosen item of <code>items</code></td></tr></tbody></table><p>The actions are <code>settings</code>, <code>share</code>, <code>publish</code>, <code>copy</code>, <code>move</code>, <code>ungroup</code> and <code>delete</code> (the type <code>KebabAction</code>).</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The trigger is a ghost icon button with an ellipsis, of the size its container declares, named by the <code>actions</code> message. It opens a <a href="./dropdown">Dropdown</a> menu at its right edge, with the keys of a menu. The actions come in the fixed order above, whatever the order given, each with its icon; <code>delete</code> comes last, after a divider, in red, with an ellipsis after its name. Choosing an action closes the menu. The names are the messages <code>settings</code>, <code>share</code>, <code>linkShare</code>, <code>duplicate</code>, <code>move</code>, <code>ungroup</code> and <code>delete</code>. With <code>items</code>, the menu is a <a href="./../workbench/menu-list">MenuList</a> of the model instead, with its submenus, and the fixed actions do not show.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/kebab/" title="Kebab" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/kebab/" target="_blank" rel="noopener">Kebab</a></figcaption></figure>',11)])])}const p=t(i,[["render",n]]);export{b as __pageData,p as default};
